{#- dacs-font: one font on every server — Liberation Sans (Arial's letter widths) shipped in the app
    (public/fonts), so a print measures and looks the same on local and live (docs/print-formats.md › Font) -#}
{%- set dacs_base = frappe.utils.get_url() -%}
<style>
@font-face { font-family: 'Arial'; src: url('{{ dacs_base }}/assets/erp_dacsinc_custom/fonts/LiberationSans-Regular.ttf') format('truetype'); font-weight: normal; font-style: normal; }
@font-face { font-family: 'Arial'; src: url('{{ dacs_base }}/assets/erp_dacsinc_custom/fonts/LiberationSans-Bold.ttf') format('truetype'); font-weight: bold; font-style: normal; }
@font-face { font-family: 'Arial'; src: url('{{ dacs_base }}/assets/erp_dacsinc_custom/fonts/LiberationSans-Italic.ttf') format('truetype'); font-weight: normal; font-style: italic; }
@font-face { font-family: 'Arial'; src: url('{{ dacs_base }}/assets/erp_dacsinc_custom/fonts/LiberationSans-BoldItalic.ttf') format('truetype'); font-weight: bold; font-style: italic; }
body, body * { font-family: Arial !important; }
/* uniform top margin: the PDF page header (letter head, or the format's own company / store header) starts
   10mm from the top of the paper on every format (Frappe's header template pulls a letter head to the edge) */
body[onload] .wrapper > :first-child { margin-top: -7.5mm !important; }
</style>
{#- Sales Invoice copies: Format 4 once per copy with its label (Original / Duplicate / Triplicate /
    Quadruplicate). Format 4 puts its letter head + heading in a #header-html block, which the PDF
    turns into ONE page header for every page (so every copy read the first label) — here each copy
    gets that block back in its own body. A return prints as "Credit Note DAC" (it does the copies). -#}
{% if doc.is_return %}{{ frappe.get_print("Sales Invoice", doc.name, "Credit Note DAC", no_letterhead=no_letterhead) }}{% else %}
<style>
    .print-copy-wrapper { page-break-after: always !important; display: block !important; clear: both; width: 100%; }
    .print-copy-wrapper:last-child { page-break-after: auto !important; }
</style>
{% set print_all_val = frappe.form_dict.get('print_all') | string %}
{% set copy_param = frappe.form_dict.get('copy_name') %}
{% if doc.docstatus == 0 %}
    {% set copy_list = ["DRAFT COPY"] %}
{% elif print_all_val == "1" %}
    {% set copy_list = ["Original", "Duplicate", "Triplicate", "Quadruplicate"] %}
{% elif copy_param %}
    {% set copy_list = [copy_param] %}
{% else %}
    {% set copy_list = ["Original"] %}
{% endif %}
{% set raw_html = frappe.get_print("Sales Invoice", doc.name, "Sales invoice Print format 4", no_letterhead=no_letterhead) %}
{% set raw_html = raw_html | replace('id="header-html" class="hidden-pdf"', 'class="dacs-copy-head"') %}
{#- the letter head prints once as the PDF page header (every page); each copy keeps its heading strip -#}
{% set raw_html = raw_html | replace('<div class="letter-head">', '<div class="letter-head" style="display: none;">') %}
{% set raw_html = raw_html | replace('id="footer-html"', 'data-dacs="inner-footer" style="display: none;"') %}
{#- the letter head is the PDF page header, so it prints on every page (docs/print-formats.md › Page header) -#}
<div id="header-html" class="hidden-pdf">{% if letter_head and not no_letterhead %}<div class="letter-head">{{ letter_head }}</div>{% endif %}
{#- the document no. / date on every page after the first, top right above the letter head (takes no room):
    page 1 has them in its heading; the page header
    is the same on every page, so the line is only made invisible on page 1 (as "Page X of Y", from the
    page number the PDF engine passes) -#}
<div class="dacs-contd" style="position: absolute; top: 3mm; right: 0; font-size: 8pt; text-align: right;">Tax Invoice No: <strong>{{ doc.name }}</strong> &nbsp;|&nbsp; Date: <strong>{{ frappe.utils.formatdate(doc.posting_date, "dd-MMM-yyyy") }}</strong> &nbsp;(continued)</div>
<script>(function () { var m = /[?&]page=(\d+)/.exec(window.location.search); if (!m || m[1] === '1') { var e = document.getElementsByClassName('dacs-contd'); for (var i = 0; i < e.length; i++) e[i].style.visibility = 'hidden'; } })();</script>
</div>
<div id="footer-html" class="visible-pdf"><p class="text-center small page-number visible-pdf" style="font-size:7.5pt;">Page <span class="page"></span> of <span class="topage"></span></p></div>
{% for label_text in copy_list %}
    <div class="print-copy-wrapper">
        {{ raw_html | replace("REPLACE_THIS_LABEL", label_text) }}
    </div>
{% endfor %}
{% endif %}
